function offplan_country_ad_scope_salt(string $path, int $id): string {
    $scope = [get_current_blog_id(), home_url('/'), $path, $id, OFFPLAN_COUNTRY_AD_NOTICE];
    return hash_hmac('sha256', 'bsre-country-ads-scope-v2|' . serialize($scope), wp_salt('auth'));
}

function offplan_country_ad_identity(string $session, string $salt, int $now): array {
    $saved = consent_cookie_subject($_COOKIE[OFFPLAN_COUNTRY_AD_PREFERENCE] ?? null, $salt, $now);
    // Initial overlapping writes share the transport's identity without restoring
    // a saved choice until the browser presents its signed preference cookie.
    // This namespace cannot read a pre-upgrade transport-session subject.
    $subject = $saved ?? substr(hash_hmac('sha256', 'bsre-country-ads-initial-v2|' . $session, $salt), 0, 32);
    return ['opaque' => $subject, 'key' => hash_hmac('sha256', 'bsre-country-ads-subject-v2|' . $subject, $salt),
        'persistent' => $saved !== null];
}

function offplan_country_ad_choice_base(string $subject, int $revision, string $salt): string {
    return 'ac1.' . $revision . '.' . hash_hmac('sha256', 'bsre-country-ads-choice-base-v1|' . $subject . '|' . $revision, $salt);
}

